<script setup>
import { Link, useForm } from '@inertiajs/vue3';
import AssessmentLayout from './AssessmentLayout.vue';
const props = defineProps({ submission:Object });
const form = useForm({ status:props.submission.status || 'Pending', grade:props.submission.grade ?? null, earned_exp:props.submission.earned_exp ?? 0, earned_gold:props.submission.earned_gold ?? 0, content:props.submission.content || '', feedback:props.submission.feedback || '', redesign_form:1 });
const save = () => form.patch(route('admin.submissions.manage.update',props.submission.uuid));
</script>
<template>
  <AssessmentLayout title="Edit submission" :subtitle="`${submission.user?.name || 'Peserta'} / ${submission.quest?.title || 'Quest'}`"><div class="layout"><form class="panel" @submit.prevent="save"><h2>Informasi edit submission</h2><p class="muted">Perubahan status dan reward mengikuti aturan penilaian aplikasi.</p><div class="fields"><label>Status<select v-model="form.status"><option value="Pending">Menunggu</option><option value="Approved">Disetujui</option><option value="Rejected">Ditolak</option></select><small class="error">{{ form.errors.status }}</small></label><label>Grade (0–100)<input v-model.number="form.grade" type="number" min="0" max="100" /><small class="error">{{ form.errors.grade }}</small></label><label>Earned EXP<input v-model.number="form.earned_exp" type="number" min="0" :disabled="form.status!=='Approved'" /><small class="error">{{ form.errors.earned_exp }}</small></label><label>Earned gold<input v-model.number="form.earned_gold" type="number" min="0" :disabled="form.status!=='Approved'" /><small class="error">{{ form.errors.earned_gold }}</small></label><label class="wide">Content<textarea v-model="form.content" rows="5" required /><small class="error">{{ form.errors.content }}</small></label><label class="wide">Feedback<textarea v-model="form.feedback" rows="5" /><small class="error">{{ form.errors.feedback }}</small></label></div><div class="actions"><button class="primary" :disabled="form.processing">{{ form.processing ? 'Menyimpan...' : 'Simpan perubahan' }}</button><Link class="secondary" :href="route('redesign.submissions')">Batal</Link></div></form><aside><section class="panel"><h2>Panduan pengisian</h2><p class="muted">Reward hanya berlaku untuk submission yang disetujui dan memenuhi syarat reward.</p></section><section class="panel"><h2>Konteks submission</h2><p class="muted">Attempt {{ submission.attempt_number || 1 }} · {{ submission.reward_eligible ? 'Reward eligible' : 'Tidak memenuhi syarat reward' }}</p><Link :href="route('redesign.submissions.inspect',submission.uuid)">Buka inspeksi</Link></section></aside></div></AssessmentLayout>
</template>
